import { useId, useRef, useState } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правит материалы' },
  { value: 'admin', label: 'Администратор', meta: 'управляет командой' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [sending, setSending] = useState(false);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const emailRef = useRef<HTMLInputElement>(null);
  const formTitleId = useId();

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText =
    touched && !isValid
      ? email.trim().length === 0
        ? 'Укажите почту приглашаемого'
        : 'Похоже, это не адрес почты: нужен вид name@example.com'
      : undefined;

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid || sending) {
      emailRef.current?.focus();
      return;
    }
    setSending(true);
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
    setSending(false);
  };

  const dismiss = () => {
    setInvitedEmail(null);
    emailRef.current?.focus();
  };

  return (
    <form
      onSubmit={submit}
      aria-labelledby={formTitleId}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        maxWidth: 440,
        padding: 20,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <h2
        id={formTitleId}
        style={{
          margin: 0,
          fontFamily: 'var(--jx-font-display)',
          fontSize: 18,
          color: 'var(--jx-text)',
        }}
      >
        Приглашение в команду
      </h2>

      {invitedEmail !== null && (
        <div
          role="status"
          style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}
        >
          <div style={{ flex: 1, minWidth: 0 }}>
            <JxAlert intent="success" title="Приглашение отправлено">
              <span style={{ wordBreak: 'break-word' }}>
                {invitedEmail} получит доступ как «
                {ROLE_OPTIONS.find((option) => option.value === role)?.label}».
                {notify
                  ? ' Уведомление на почту отправлено.'
                  : ' Уведомление на почту не отправлялось.'}
              </span>
            </JxAlert>
          </div>
          <JxButton
            variant="ghost"
            size="sm"
            iconOnly
            aria-label="Закрыть сообщение об отправке"
            onClick={dismiss}
          >
            ✕
          </JxButton>
        </div>
      )}

      <JxInputField
        ref={emailRef}
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        helperText="Приглашение придёт на этот адрес и будет действовать 7 дней"
        errorText={errorText}
      />

      <JxSelect
        label="Роль в команде"
        placeholder="Выберите роль"
        options={ROLE_OPTIONS}
        value={role}
        onValueChange={setRole}
      />

      <JxSwitch
        name="notify"
        label="Отправить уведомление на почту"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary" disabled={!isValid || sending}>
          Отправить приглашение
        </JxButton>
      </div>
    </form>
  );
}

